import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {World,exitDestination,completionPercent} from '../dist/js/engine.js';
import {encodeReplay,Demo,inputFromMask,passwordFor,parsePassword} from '../dist/js/compat.js';
const root=new URL('../dist/',import.meta.url),json=async n=>JSON.parse(await readFile(new URL(n,root),'utf8')),buf=async n=>new Uint8Array(await readFile(new URL('assets/'+n,root)));
const a={game:await json('assets/game.json'),rules:await json('rules.json'),tables:await buf('tables.bin'),maps:{},footers:{}};
for(const l of a.game.levels){a.maps[l.id]=await buf(l.map);a.footers[l.id]=await buf(l.footer);}
test('all sixteen stages simulate mixed movement and attacks without invalid positions',()=>{for(let i=0;i<16;i++){const w=new World(a);w.loadLevel(i);for(let n=0;n<1200;n++){w.step({right:n%200<100,left:n%200>=100,up:n%45<15,attack:n%7<4,down:n%100>95});assert.ok(Number.isFinite(w.player.x)&&Number.isFinite(w.player.y),`stage ${i} tick ${n}`);}assert.ok(w.health>=0&&w.health<=3);}});
test('recorded input produces the same state at fixed ticks',()=>{const masks=Array.from({length:900},(_,i)=>(i%100<80?2:1)|(i%33<13?4:0)|(i%6<3?16:0)),d=new Demo(encodeReplay(masks)),x=new World(a),y=new World(a);for(const m of masks){x.step(inputFromMask(m));y.step(inputFromMask(d.next()));assert.equal(x.stateHash(),y.stateHash());}});
test('level one supports standing, walking and variable jump',()=>{const w=new World(a);for(let n=0;n<20;n++)w.step({});const start={...w.player};assert.ok(start.grounded);for(let n=0;n<8;n++)w.step({right:true});assert.ok(w.player.x>start.x);w.step({up:true});assert.ok(w.player.vy<0);assert.ok(w.player.y<start.y);});
test('campaign and secret exits follow recovered transition graph',()=>{assert.equal(exitDestination(0),1);assert.equal(exitDestination(1),12);assert.equal(exitDestination(12),2);assert.equal(exitDestination(2,'special'),13);assert.equal(exitDestination(13,'special'),3);assert.equal(exitDestination(6,'special'),15);assert.equal(exitDestination(15,'special'),7);assert.equal(completionPercent(2,3,5,5),50);});
test('checkpoint retains destroyed secrets and collected permanent food across death',()=>{const w=new World(a);const block=w.blocks.find(b=>b.pos<w.map.length);block.active=false;w.map[block.pos]=block.replacement;w.checkpoint={x:120,y:600};w.loadLevel(0,{restart:true});assert.deepEqual(w.checkpoint,{x:120,y:600});assert.equal(w.map[block.pos],block.replacement);assert.equal(w.player.x,120);assert.equal(w.player.y,600);});
test('browser passwords round trip all campaign levels and difficulties',()=>{for(let i=0;i<10;i++)for(const expert of [false,true])assert.deepEqual(parsePassword(passwordFor(i,expert)),{level:i,expert});assert.equal(parsePassword('NOPE'),null);});
test('key pickup opens authored closed exits and exit pickup enters transition',()=>{const w=new World(a);const exits=w.items.filter(i=>(i.sprite&0x1fff)===0x116);assert.ok(exits.length);w.pickup({sprite:0x63,x:0,y:0,active:true});assert.ok(exits.every(i=>(i.sprite&0x1fff)===0x117));w.pickup(exits[0]);assert.equal(w.transition.type,'complete');assert.equal(w.transition.next,1);for(let i=0;i<58;i++)w.step({});w.advance();assert.equal(w.levelIndex,1);});
test('zero-durability authored block breaks once and changes only its tile',()=>{const w=new World(a);const b=w.blocks.find(b=>b.pos<w.map.length);b.durability=0;const before=w.map.slice();w.hitBlock(b);assert.equal(w.brokenBlocks,1);assert.equal(w.map[b.pos],b.replacement);w.hitBlock(b);assert.equal(w.brokenBlocks,1);for(let i=0;i<w.map.length;i++)if(i!==b.pos)assert.equal(w.map[i],before[i]);});
test('damage at zero health consumes one spare life and restart checkpoint',()=>{const w=new World(a);for(let n=0;n<4;n++){w.player.invulnerable=0;w.damage();}assert.equal(w.health,0);assert.ok(w.deathTimer>0);for(let n=0;n<38;n++)w.step({});assert.equal(w.health,3);assert.equal(w.lives,1);});
test('standing follows the original breathing/blinking stream without moving the player',()=>{const w=new World(a);const frames=[];for(let n=0;n<50;n++){w.step({});frames.push(w.player.sprite&0x1fff);assert.equal(w.player.x,42);assert.equal(w.player.y,672);}assert.ok(frames.includes(9));assert.ok(frames.includes(10));assert.ok(frames.includes(8));assert.equal(w.player.action,0);assert.equal(w.player.animationVariant,17);});
test('idle look and post-walk gestures use the distinct original secondary streams',()=>{const w=new World(a);for(let i=0;i<8;i++)w.step({look:true});assert.ok([29,31].includes(w.player.sprite&0x1fff));assert.equal(w.player.animationVariant,19);w.player.walkHistory=30;w.step({});assert.equal(w.player.sprite&0x1fff,6);assert.equal(w.player.walkHistory,27);});
test('club attack completes all seven original body/weapon frames, including its strike marker',()=>{const w=new World(a);w.step({});const body=[],club=[];for(let i=0;i<7;i++){w.step({attack:i===0});body.push(w.player.sprite&0x1fff);club.push(w.playerWeapon?.sprite&0x1fff);assert.ok(w.playerWeapon);}assert.deepEqual(body,[34,34,35,35,36,36,36]);assert.deepEqual(club,[58,58,59,59,60,60,60]);assert.equal(w.player.marker&0x4000,0x4000);w.step({});assert.equal(w.playerWeapon,null);});
test('each weapon overlay uses its original pose offsets and mirrors with player facing',()=>{for(let weapon=0;weapon<4;weapon++)for(const face of [-1,1]){const w=new World(a);w.weapon=weapon;w.player.face=face;w.player.sprite=34|(face<0?0x8000:0);w.updatePlayerWeapon();const table=w.word(0x7b00+weapon*5);assert.equal(w.playerWeapon.sprite,w.word(table+2)|(face<0?0x8000:0));assert.equal(w.playerWeapon.x,w.player.x-face*w.signedWord(table+4));assert.equal(w.playerWeapon.y,w.player.y-w.signedWord(table+6));}});

// Flat/empty fixtures isolate recovered player routines from authored enemies/items.
function playerFixture(){const w=new World(a);w.definitions=[];w.items=[];w.blocks=[];w.platforms=[];w.boss=null;w.level={...w.level,tilePropertiesX:new Array(256).fill(0),tilePropertiesY:new Array(256).fill(0),tilePropertiesMisc:new Array(256).fill(0),tileSlopes:new Array(256).fill(0),scrollFlags:0};w.level.tilePropertiesX[1]=1;w.level.tilePropertiesY[1]=1;w.level.tilePropertiesMisc[1]=1;w.map.fill(0);w.map.fill(1,40*256);Object.assign(w.player,{x:100,y:640,grounded:true,lastGroundY:640});w.camera={x:0,y:544};return w;}
test('walking uses original doubled frames and fixed-point acceleration in both directions',()=>{for(const face of [-1,1]){const w=playerFixture(),out=[];for(let i=0;i<6;i++){w.step(face<0?{left:true}:{right:true});out.push([w.player.vx,w.player.x,w.player.sprite&0x1fff]);}assert.deepEqual(out.map(x=>x[0]),[16,32,48,64,80,80].map(x=>x*face));assert.deepEqual(out.map(x=>x[1]),[1,3,6,10,15,20].map(x=>100+x*face));assert.deepEqual(out.map(x=>x[2]),[0,0,1,1,2,2]);}});
test('held jump follows nine signed impulses and original double gravity after impulse nine',()=>{const w=playerFixture(),out=[];for(let i=0;i<11;i++){w.step({up:true});out.push([w.player.y,w.player.vy]);}assert.deepEqual(out,[[635,-49],[628,-84],[620,-103],[612,-107],[604,-101],[597,-90],[591,-76],[586,-61],[582,-45],[580,-13],[580,19]]);});
test('released jump preserves its rising pose and selects fall frame only after descending',()=>{const w=playerFixture();w.step({up:true});for(let i=0;i<3;i++){w.step({});assert.ok(w.player.vy<0);assert.equal(w.player.sprite&0x1fff,11);}w.step({});assert.ok(w.player.vy>0);assert.equal(w.player.sprite&0x1fff,12);});
test('fall pose changes after twelve previous descending updates, not before',()=>{for(const [fall,sprite] of [[11,12],[12,13]]){const w=playerFixture();w.map.fill(0);Object.assign(w.player,{y:200,vy:64,fallFrames:fall});w.step({});assert.equal(w.player.sprite&0x1fff,sprite);assert.equal(w.player.fallFrames,fall+1);}});
test('moving crouch decelerates gradually above cap and uses original four-tick poses',()=>{const w=playerFixture();w.player.vx=80;const out=[];for(let i=0;i<5;i++){w.step({right:true,down:true});out.push([w.player.vx,w.player.sprite&0x1fff]);}assert.deepEqual(out,[[68,21],[56,21],[44,21],[32,21],[32,22]]);});
test('crouching charges the attack counter with original increment/decrement cadence',()=>{const w=playerFixture();for(let i=0;i<50;i++)w.step({down:true});assert.equal(w.power,48);w.step({attack:true});assert.equal(w.projectiles.find(p=>p.contact)?.damage,100);});
test('ranged attacks release on marker frame with original velocity and animated projectile table',()=>{for(const weapon of [2,3]){const w=playerFixture();w.weapon=weapon;for(let i=0;i<6;i++){w.step({attack:i===0});assert.equal(w.projectiles.filter(a=>a.ranged).length,0);}w.step({});const shot=w.projectiles.find(a=>a.ranged);assert.ok(shot);assert.equal(shot.vx,208);assert.equal(shot.vy,weapon===2?-64:-32);assert.equal(shot.sprite,weapon===2?67:274);assert.equal(w.playerWeapon,null);const x=shot.x,y=shot.y;w.step({});assert.equal(shot.x,x+13);assert.equal(shot.y,y+(weapon===2?-4:-2));assert.equal(shot.vy,weapon===2?-32:-48);for(let i=0;i<3;i++)w.step({});assert.equal(shot.sprite&0x1fff,weapon===2?91:277);}});
test('melee collision follows the visible club pose instead of a fixed forward hitbox',()=>{const w=playerFixture();w.step({attack:true});const hit=w.projectiles.find(a=>a.contact);assert.ok(hit);assert.equal(hit.sprite,w.playerWeapon.sprite);assert.equal(hit.x,w.playerWeapon.x);assert.equal(hit.y,w.playerWeapon.y);assert.equal(hit.sprite,58);assert.ok(hit.x<w.player.x);});
test('attack finishing frame sets weapon cooldown, sound and action-specific vertical kick',()=>{for(const [input,action,kick,frames] of [[{attack:true},3,-32,7],[{attack:true,up:true},6,0,9],[{attack:true,down:true},7,-48,9]]){const w=playerFixture(),sounds=[];w.onEvent=e=>{if(e.type==='sfx')sounds.push(e.index);};for(let i=0;i<frames-1;i++)w.step(i===0?input:{});assert.deepEqual(sounds,[]);w.step({});assert.equal(w.player.attackAction,action);assert.ok(sounds.includes(5));assert.equal(w.player.attackActive,false);assert.equal(w.player.attackCooldown,1);assert.equal(w.player.vy,kick===0?0:kick+16);}});
test('long landing bounces only when the original fall/distance/speed gates pass',()=>{const w=playerFixture();Object.assign(w.player,{fallFrames:11,lastGroundY:500,vy:96});w.landPlayer(640);assert.equal(w.player.vy,-32);assert.equal(w.player.sprite&0x1fff,12);assert.equal(w.player.fallFrames,0);w.level.scrollFlags=1;Object.assign(w.player,{fallFrames:11,lastGroundY:500,vy:96});w.landPlayer(640);assert.equal(w.player.vy,96);Object.assign(w.player,{fallFrames:20,lastGroundY:300,vy:192});w.landPlayer(640);assert.equal(w.player.landingShake,8);});
test('ordinary enemy knockback multiplies prior horizontal speed and form absorbs the hit',()=>{const w=playerFixture();w.player.vx=80;w.damage();assert.equal(w.player.vx,-320);assert.equal(w.player.vy,-128);assert.equal(w.player.invulnerable,44);assert.equal(w.health,2);const f=playerFixture();f.alternate=true;f.damage();assert.equal(f.alternate,false);assert.equal(f.health,3);assert.equal(f.player.glideMode,0);});
test('hurt pose includes the exact timer22 boundary',()=>{const w=playerFixture();w.player.invulnerable=22;w.step({right:true});assert.equal(w.player.sprite&0x1fff,33);assert.equal(w.player.action,8);w.step({right:true});assert.equal(w.player.action,1);});
test('form uses original run/idle/fall art and separate attachment',()=>{const w=playerFixture();w.alternate=true;w.step({});assert.equal(w.player.sprite&0x1fff,47);assert.equal(w.playerWeapon.sprite,119);w.step({right:true});assert.equal(w.player.sprite&0x1fff,39);w.step({up:true});assert.equal(w.player.sprite&0x1fff,45);assert.equal(w.player.vy,-17);});
test('running form jump activates gliding without applying a jump impulse',()=>{const w=playerFixture();w.alternate=true;Object.assign(w.player,{runTimer:24,vy:0});w.step({up:true});assert.equal(w.player.y,637);assert.equal(w.player.vy,4);assert.equal(w.player.glideMode,1);assert.equal(w.player.glideEnergy,24);assert.equal(w.player.runTimer,0);assert.equal(w.player.sprite&0x1fff,50);assert.equal(w.playerWeapon.sprite,121);});
test('glider controls spend/recharge energy, change angle and use mode-specific gravity',()=>{const w=playerFixture();w.alternate=true;Object.assign(w.player,{glideMode:1,glideEnergy:3,formAngle:3,vy:0,y:400});w.step({up:true});assert.equal(w.player.glideEnergy,2);assert.equal(w.player.formAngle,4);assert.equal(w.player.vy,-60);Object.assign(w.player,{glideMode:1,glideEnergy:0,formAngle:1,vx:80,vy:0});w.step({down:true});assert.equal(w.player.glideMode,3);assert.equal(w.player.glideEnergy,5);assert.equal(w.player.vy,16);assert.equal(w.player.sprite&0x1fff,51);assert.equal(w.playerWeapon.sprite,124);});
test('landing dust advances original five sprites without introducing a sound effect',()=>{const w=playerFixture();Object.assign(w.player,{fallFrames:5,lastGroundY:630,vy:64});w.landPlayer(640);assert.ok(w.effects.some(e=>e.dust&&e.sprite===53));assert.ok(!w.events.some(e=>e.type==='sfx'));for(let i=0;i<4;i++){w.updateEffects();assert.equal(w.effects.find(e=>e.dust).sprite,54+i);}w.updateEffects();assert.ok(!w.effects.some(e=>e.dust));});
test('long landing records the new ground height before the bounce shared-tail return',()=>{const w=playerFixture();Object.assign(w.player,{fallFrames:11,lastGroundY:500,vy:96});w.landPlayer(640);assert.equal(w.player.lastGroundY,640);});
test('platform landing retains glide mode and does not trigger the floor bounce',()=>{const w=playerFixture();Object.assign(w.player,{glideMode:1,fallFrames:20,vy:192});w.landPlatform(600);assert.equal(w.player.glideMode,1);assert.equal(w.player.vy,0);assert.equal(w.player.platformGrip,true);assert.ok(!w.effects.some(e=>e.dust));});
test('alternate jump bypasses normal jump lock, both before and after glide charge',()=>{for(const timer of [0,24]){const w=playerFixture();w.alternate=true;Object.assign(w.player,{jumpLock:6,runTimer:timer});w.step({up:true});assert.equal(w.player.y,637);assert.equal(w.player.glideMode,timer===24?1:0);assert.equal(w.player.vy,timer===24?4:-17);}});
test('final melee frame is hidden during descent and airborne contact hits cause the original bounce',()=>{const w=playerFixture();w.player.sprite=36;w.player.marker=0x4000;w.player.fallFrames=2;w.updatePlayerWeapon();assert.equal(w.playerWeapon,null);w.player.vy=32;const hit={ttl:1,contact:true};w.consumeAttack(hit);assert.equal(w.player.vy,-80);assert.equal(hit.ttl,0);w.player.vy=32;w.consumeAttack({ttl:1,ranged:true});assert.equal(w.player.vy,32);});
