test('damage inflicted in contact phase loses one immunity tick at presentation, not before collision',()=>{const w=playerFixture();w.checkActorDamage=()=>w.damage();w.step({});assert.equal(w.player.invulnerable,43);assert.equal(w.health,2);});
test('ceiling impact preserves remaining jump impulse index and rejects world-edge moves',()=>{const w=playerFixture();Object.assign(w.player,{y:580,vy:-64,jumpFrame:3});w.map[(34<<8)|6]=1;w.collidePlayer(100,584);assert.equal(w.player.vy,0);assert.equal(w.player.jumpFrame,3);const e=playerFixture();e.player.x=4086;e.player.vx=80;e.step({right:true});assert.equal(e.player.x,4086);});
test('blocked held jump uses the original idle shared-tail first jump pose until lock expires',()=>{const w=playerFixture();w.player.jumpLock=6;w.step({up:true});assert.equal(w.player.sprite&0x1fff,11);assert.equal(w.player.action,0);assert.equal(w.player.y,640);assert.equal(w.player.jumpFrame,0);assert.equal(w.player.jumpLock,5);});
test('alternate controller remains finite and references valid original sprites in every stage',()=>{for(let i=0;i<16;i++){const w=new World(a);w.loadLevel(i);for(let n=0;n<600;n++){w.alternate=true;w.step({right:n%180<90,left:n%180>=90,up:n%65<35,down:n%65>=50,attack:n%19===0});assert.ok(Number.isFinite(w.player.x)&&Number.isFinite(w.player.y));assert.ok(a.game.sprites[w.player.sprite&0x1fff]);if(w.playerWeapon)assert.ok(a.game.sprites[w.playerWeapon.sprite&0x1fff]);}}});

test('all gate records match the twenty packed seven-byte footer entries',()=>{for(const l of a.game.levels){assert.equal(l.gates.length,20);for(const [i,g] of l.gates.entries()){const raw=Array.from(a.footers[l.id].slice(1289+i*7,1296+i*7));assert.deepEqual(g.raw,raw);assert.equal(g.triggerTile,raw[0]|raw[1]<<8);assert.equal(g.cameraTile,raw[2]|raw[3]<<8);assert.equal(g.destinationTile,raw[4]|raw[5]<<8);assert.equal(g.cameraFlag,raw[6]);}}});
test('every authored level-one gate, including previously omitted odd return records, teleports on buffered Down',()=>{for(const g of a.game.levels[0].gates.filter(g=>g.active)){const w=new World(a);Object.assign(w.player,{x:(g.triggerTile&255)*16,y:(g.triggerTile>>8)*16,downTimer:3,vx:64,vy:32});w.input={};w.checkGates();assert.equal(w.player.x,(g.destinationTile&255)*16,`gate ${g.index}`);assert.equal(w.player.y,(g.destinationTile>>8)*16);assert.equal(w.player.vx,0);assert.equal(w.player.vy,0);assert.equal(w.player.downTimer,0);assert.equal(w.camera.x,(g.cameraTile&255)*16);assert.equal(w.camera.y,(g.cameraTile>>8)*16);assert.equal(w.gateCameraFlag,g.cameraFlag);if(g.cameraFlag){const c={...w.camera};w.updateCamera();assert.deepEqual(w.camera,c);}}});
test('cave route can return immediately using its authored counterpart without a synthetic cooldown',()=>{const w=new World(a),enter=w.gates[14],exit=w.gates[13];Object.assign(w.player,{x:(enter.triggerTile&255)*16,y:(enter.triggerTile>>8)*16,downTimer:3});w.checkGates();assert.equal(w.tilePos(w.player.x,w.player.y),exit.triggerTile);w.player.downTimer=3;w.checkGates();assert.equal(w.tilePos(w.player.x,w.player.y),exit.destinationTile);assert.equal(w.gateCameraFlag,0);});
test('gates reject absent Down and the alternate form',()=>{const w=new World(a),g=w.gates[14];Object.assign(w.player,{x:(g.triggerTile&255)*16,y:(g.triggerTile>>8)*16,downTimer:0});w.checkGates();assert.equal(w.tilePos(w.player.x,w.player.y),g.triggerTile);w.player.downTimer=3;w.alternate=true;w.checkGates();assert.equal(w.tilePos(w.player.x,w.player.y),g.triggerTile);});
test('bear patrol with raw delay255 spawns on camera and uses fixed-point speed cap48',()=>{const w=new World(a),d=w.definitions.find(d=>d.type===9);assert.equal(d.pause_candidate,255);w.definitions=[d];w.player.x=1534;w.player.y=528;w.camera={x:1408,y:400};w.spawnActors();assert.equal(w.actors.length,1);const bear=w.actors[0];assert.equal(bear.sprite&0x1fff,313);assert.equal(bear.vx,0);w.updateActors();assert.equal(bear.vx,0);w.updateActors();assert.equal(bear.vx,3);for(let n=0;n<100;n++){w.updateActors();assert.ok(Math.abs(bear.vx)<=48);assert.ok(a.game.sprites[bear.sprite&0x1fff]);}});
