test('emergence timer does not bypass its packed trigger rectangle',()=>{const w=new World(a);w.definitions=w.definitions.filter(d=>d.type===10);w.player.x=42;w.player.y=672;for(let i=0;i<200;i++)w.spawnActors();assert.equal(w.actors.length,0);});
test('negative-one enemy facing sentinel never integrates as a leftward velocity',()=>{const w=playerFixture(),d={extra:new Uint8Array(),flags:0,timer:0,active:true};const actor={x:120,y:640,vx:-1,vy:0,state:0,age:0,type:1,def:d,active:true,sprite:317};w.actors=[actor];w.updateActors();assert.equal(actor.x,120);});
test('ordinary full updates activate the previously omitted level-one cave return triggers',()=>{for(const i of [13,15,17]){const w=new World(a),g=w.gates[i];w.definitions=[];w.items=[];Object.assign(w.player,{x:(g.triggerTile&255)*16,y:(g.triggerTile>>8)*16,lastGroundY:(g.triggerTile>>8)*16,grounded:true});w.step({down:true});assert.equal(w.player.x,(g.destinationTile&255)*16,`gate ${i}`);assert.equal(w.player.y,(g.destinationTile>>8)*16);}});

// Trace fixtures exercise native callbacks using authored definitions and animation streams.
function enemyFixture(type){const l=a.game.levels.find(l=>l.enemies.some(d=>d.type===type&&!d.expert_flag)),w=new World(a);w.loadLevel(a.game.levels.indexOf(l));const d=w.definitions.find(d=>d.type===type);w.definitions=[d];w.items=[];w.blocks=[];w.platforms=[];w.level={...w.level,tilePropertiesX:Array(256).fill(0),tilePropertiesY:Array(256).fill(0),tileSlopes:Array(256).fill(0)};w.map.fill(0);w.camera={x:0,y:400};Object.assign(w.player,{x:160,y:500,vx:0,vy:0,sprite:9});Object.assign(d,{x:128,y:500,active:true,flags:5,timer:0});const actor={x:128,y:500,vx:0,vy:0,sprite:d.sprite,face:1,state:0,age:0,hp:d.hitpoint_candidate,aux:0,active:true,type,def:d};actor.animStart=actor.anim=w.secondaryAnimationFor(d.sprite&0x1fff,type);w.actors=[actor];return {w,d,actor};}
test('head landing preserves enemy HP and holds jump for the original higher bounce',()=>{for(const [up,expected] of [[false,-64],[true,-224]]){const {w,actor}=enemyFixture(9),height=a.game.sprites[actor.sprite&0x1fff].height;Object.assign(w.player,{x:actor.x,y:actor.y-height+2,vy:32,jumpLock:6,fallFrames:15});w.input={up};const hp=actor.hp;w.checkActorDamage();assert.equal(w.player.vy,expected);assert.equal(w.player.y,actor.y-height);assert.equal(w.player.jumpLock,6);assert.equal(w.player.fallFrames,0);assert.equal(w.health,3);assert.equal(actor.hp,hp);assert.equal(actor.aux,4);}});
test('side contact and upward contact cause damage instead of a head bounce',()=>{for(const vy of [0,-32]){const {w,actor}=enemyFixture(9);Object.assign(w.player,{x:actor.x,y:actor.y,vy});w.input={up:true};w.checkActorDamage();assert.equal(w.health,2);assert.equal(w.player.vy,-128);assert.equal(actor.def.flags&1,0);}});
test('normal repeated stomps emit authored bonus glyphs without adding invented score',()=>{const {w,actor}=enemyFixture(9);for(let n=0;n<4;n++){Object.assign(w.player,{x:actor.x,y:actor.y-a.game.sprites[actor.sprite&0x1fff].height+1,vy:32});w.input={};w.checkActorDamage();}assert.equal(actor.aux,16);assert.equal(w.score,0);assert.deepEqual(w.effects.map(e=>e.sprite),[224,225]);});
test('gliding form scores three stomps and launches defeated enemy on the third',()=>{const {w,actor}=enemyFixture(9);w.alternate=true;w.player.glideMode=1;for(let n=0;n<3;n++){Object.assign(w.player,{x:actor.x,y:actor.y-a.game.sprites[actor.sprite&0x1fff].height+1,vy:64});w.input={};w.checkActorDamage();if(n<2)assert.equal(w.player.vy,-96);}assert.equal(w.score,1600);assert.equal(actor.state,255);assert.equal(actor.vy,-200);});
test('weapon damage uses unsigned borrow, immediate repeat hits and native recoil',()=>{const {w,actor}=enemyFixture(9);actor.hp=25;actor.vx=48;const shot=()=>({x:actor.x,y:actor.y,sprite:58,face:1,ttl:1,damage:25,contact:true});w.player.vy=32;w.projectiles=[shot()];w.checkEnemyAttacks();assert.equal(actor.hp,0);assert.notEqual(actor.state,255);assert.equal(actor.x,116);assert.equal(w.player.vy,-80);w.projectiles=[shot()];w.checkEnemyAttacks();assert.equal(actor.state,255);assert.equal(actor.active,true);assert.equal(actor.vy,-200);assert.equal(actor.vx,100);assert.ok(w.word(actor.anim)<0x7d00);});
test('off-screen dead enemies retire while reusable definitions survive',()=>{const {w,actor,d}=enemyFixture(9);d.flags|=2;w.killActor(actor);actor.y=900;w.updateDeadActor(actor);assert.equal(actor.active,false);assert.equal(d.destroyed,false);assert.equal(d.active,false);});
test('secret initialization conceals all four early platform tiles with the authored blank tile',()=>{const w=new World(a);for(const index of [76,77,78,79]){const b=w.blocks.find(b=>b.index===index);assert.equal(b.durability,0x41);assert.equal(w.map[b.pos],126);assert.equal(w.level.lookup[w.map[b.pos]],256);assert.equal(b.replacement,a.maps['1'][b.pos]);}assert.ok(w.items.some(i=>i.sprite===227&&i.x===456&&i.y===536));});
test('two spaced club hits reveal all connected early platform tiles and no bogus pickup sprite',()=>{const w=new World(a),b=w.blocks.find(b=>b.index===79),before=w.items.length;w.hitBlock(b);assert.equal(b.durability,0x40);assert.equal(b.active,true);w.blockCooldown=0;w.hitBlock(b);assert.equal(w.brokenBlocks,4);for(const i of [76,77,78,79]){const q=w.blocks.find(b=>b.index===i);assert.equal(q.active,false);assert.equal(w.map[q.pos],q.replacement);}assert.equal(w.items.length,before);assert.ok(w.effects.every(e=>[229,308].includes(e.sprite)));assert.ok(!w.effects.some(e=>e.collectible));assert.equal(w.floorClass(224,544),1);});
test('hidden platform responds to actual airborne club poses and stays revealed across restart',()=>{const w=new World(a),b=w.blocks.find(b=>b.index===78);w.projectiles=[{x:224,y:560,sprite:58,ttl:1,contact:true}];w.player.vy=-16;w.checkBlocks();assert.equal(w.player.vy,-80);assert.equal(b.durability,0x40);w.blockCooldown=0;w.projectiles=[{x:224,y:560,sprite:58,ttl:1,contact:true}];w.checkBlocks();w.loadLevel(0,{restart:true});assert.equal(w.map[b.pos],b.replacement);assert.equal(w.blocks.find(q=>q.index===79).active,false);});
test('secret vertical hit threshold rejects distance16 and accepts15',()=>{const w=new World(a),b=w.blocks.find(b=>b.index===79);w.blocks=[b];w.projectiles=[{x:224,y:544,sprite:58,ttl:1}];w.checkBlocks();assert.equal(b.durability,0x41);w.projectiles=[{x:224,y:545,sprite:58,ttl:1}];w.checkBlocks();assert.equal(b.durability,0x40);});
test('temporary enemy power is earned from three authored inventory bits and expires',()=>{const {w,actor}=enemyFixture(9);for(const c of [48,49,50])w.pickup({sprite:c+53,x:0,y:0,active:true});assert.equal(w.enemyPowerTimer,660);assert.equal(w.inventory2&0x38,0);Object.assign(w.player,{x:actor.x,y:actor.y,vy:0});w.checkActorDamage();assert.equal(w.health,3);assert.equal(actor.state,255);w.actors=[];w.enemyPowerTimer=1;w.step({});assert.equal(w.enemyPowerTimer,0);});
test('oscillating spider reverses direction only on its next callback and changes animation segment',()=>{const {w,actor,d}=enemyFixture(2);d.extra[0]=8;d.extra[1]=2;actor.y=d.y+9;const initial=actor.anim;w.updateActors();assert.equal(actor.state,1);assert.equal(actor.vy,32);assert.notEqual(actor.anim,initial+2);w.updateActors();assert.equal(actor.vy,-32);actor.y=d.y-1;actor.vy=0;w.updateActors();assert.equal(actor.state,0);});
test('swinging hazard drops to its radius before using the original signed trig table',()=>{const {w,actor,d}=enemyFixture(4);d.pause_candidate=0;d.extra.set([32,40,0,0]);for(let n=0;n<16;n++)w.updateActors();assert.equal(actor.y,d.y+32);assert.equal(actor.state,0);w.updateActors();assert.equal(actor.state,1);w.updateActors();assert.equal(actor.x,d.x);assert.equal(actor.y,d.y+32);assert.equal(d.extra[2],4);assert.equal(w.ropePoints.length,3);});
test('diagonal attacker starts downwards even when player is above, then levels out',()=>{const {w,actor,d}=enemyFixture(5);d.extra.set([20,20,3]);w.player.y=450;w.updateActors();assert.equal(actor.state,10);assert.equal(actor.vy,48);w.player.y=actor.y;actor.vy=0;w.updateActors();assert.equal(actor.state,11);assert.equal(actor.vy,0);});
test('signed diagonal charge keeps negative authored speed and advances pose stream',()=>{const {w,actor,d}=enemyFixture(7);d.extra.set([20,254]);w.updateActors();assert.equal(actor.state,10);assert.equal(actor.vy,-32);assert.equal(actor.vx,-32);});
test('flying avoidance uses eighth-pixel accumulators rather than common velocity',()=>{const {w,actor,d}=enemyFixture(6);d.extra[0]=20;w.updateActors();assert.equal(actor.state,1);w.player.attackActive=true;w.updateActors();assert.equal(d.extra[1],152);assert.equal(w.defWord(d,17),128*8-104);assert.equal(actor.x,115);assert.equal(actor.vx,1);});
test('leaper waits for its animation marker rather than an arbitrary eight ticks',()=>{const {w,actor,d}=enemyFixture(11);d.extra.set([2,4,6]);for(let i=0;i<7;i++){w.updateActors();assert.equal(actor.state,0);}for(let i=0;i<80&&actor.state===0;i++)w.updateActors();assert.equal(actor.state,1);assert.equal(d.flags&16,0);assert.equal(actor.vy,-64);assert.equal(actor.vx,32);});
test('wall-climbing enemy switches streams and climbs one tile once clear',()=>{const {w,actor,d}=enemyFixture(3);w.level.tilePropertiesX[1]=1;d.flags=0x48;actor.vx=48;w.map[w.tilePos(actor.x+16,actor.y-16)]=1;w.actorPhysics(actor);assert.equal(d.flags&0xc0,0xc0);assert.equal(actor.vy,-16);assert.equal(actor.x,140);w.map.fill(0);w.actorPhysics(actor);assert.equal(d.flags&0x80,0);assert.equal(actor.y,484);assert.equal(actor.vy,0);});
test('level-one input replay reveals early steps, bounces on a bear and reaches platform height',()=>{const w=new World(a);let bounced=false,high=false;for(let n=0;n<115;n++){w.step({right:w.player.x<230,up:true,attack:n>=59});if(w.player.vy===-224)bounced=true;if(w.player.y<=544&&w.brokenBlocks>=4)high=true;}assert.ok(bounced);assert.ok(high);assert.ok([76,77,78,79].every(i=>!w.blocks.find(b=>b.index===i).active));assert.equal(w.health,3);});
test('every authored enemy definition uses valid animation frames through a bounded activation trace',()=>{let count=0;for(let level=0;level<a.game.levels.length;level++){const source=new World(a,{expert:true});source.loadLevel(level);for(const template of source.definitions){const w=new World(a,{expert:true});w.loadLevel(level);const d=w.definitions.find(d=>d.index===template.index);w.definitions=[d];if(d.type===0||d.type===10){w.player.x=((d.x_raw&255)+Math.min(4,d.y_raw&255))*16;w.player.y=((d.x_raw>>8)+Math.min(4,d.y_raw>>8))*16;}else{w.player.x=d.x+16;w.player.y=d.y+(d.type===12?200:0);}w.camera={x:Math.max(0,w.player.x-144),y:Math.max(0,w.player.y-96)};for(let n=0;n<220;n++){w.frame++;w.updateActors();w.spawnActors();for(const actor of w.actors){assert.ok(a.game.sprites[actor.sprite&0x1fff],`level ${level} definition ${d.index} type ${d.type} sprite ${actor.sprite} tick ${n}`);assert.ok(Number.isFinite(actor.x)&&Number.isFinite(actor.y));}assert.ok(w.actors.length<=12);}count++;}}assert.equal(count,348);});
test('untouched enemies drop no bones; harmful contact enables exactly six on defeat',()=>{for(const type of [9,10,2]){for(const touched of [false,true]){const {w,actor}=enemyFixture(type);if(touched){Object.assign(w.player,{x:actor.x,y:actor.y,vy:0});w.input={};w.checkActorDamage();assert.equal(w.health,2);assert.equal(actor.def.flags&1,0);}w.killActor(actor);const bones=w.effects.filter(e=>e.nativeObject);assert.equal(bones.length,touched?6:0);assert.ok(bones.every(e=>(e.sprite&8191)===70&&e.collectible));w.killActor(actor);assert.equal(w.effects.filter(e=>e.nativeObject).length,bones.length);for(let tick=0;tick<12;tick++){w.frame++;w.updateEffects();for(const bone of bones)assert.ok((bone.sprite&8191)>=70&&(bone.sprite&8191)<=73);}}}});
test('stomps and immunity do not enable bones; loss of alternate form does per native flag order',()=>{for(const mode of ['stomp','immunity','form']){const {w,actor}=enemyFixture(9);w.input={};Object.assign(w.player,{x:actor.x,y:actor.y,vy:0});if(mode==='stomp'){w.player.y=actor.y-30;w.player.vy=128;}if(mode==='immunity')w.player.invulnerable=20;if(mode==='form')w.alternate=true;w.checkActorDamage();assert.equal(w.health,3);assert.equal(actor.def.flags&1,mode==='form'?0:1);w.killActor(actor);assert.equal(w.effects.filter(e=>e.nativeObject).length,mode==='form'?6:0);}});
test('collecting six bear bones restores one heart without changing weapon and cannot collect twice',()=>{const {w,actor}=enemyFixture(9);w.health=2;w.weapon=0;actor.def.flags&=~1;w.killActor(actor);const bones=w.effects.filter(e=>e.nativeObject);w.effects=[...bones];for(const bone of bones)bone.ttl=188;for(let n=0;n<6;n++){for(let j=0;j<6;j++){bones[j].x=n===j?100:1000+j*40;bones[j].y=500;}Object.assign(w.player,{x:100,y:500});w.checkPickups();assert.equal(w.foodHealth,n===5?0:n+1);assert.equal(w.health,n===5?3:2);assert.equal(w.weapon,0);}w.checkPickups();assert.equal(w.health,3);assert.equal(w.foodHealth,0);assert.ok(bones.every(b=>b.ttl===0));});
test('fresh bone bursts respect the original collection grace period',()=>{const {w,actor}=enemyFixture(9);w.health=1;actor.def.flags&=~1;w.killActor(actor);w.effects=w.effects.filter(e=>e.nativeObject);Object.assign(w.player,{x:actor.x,y:actor.y});w.checkPickups();assert.equal(w.foodHealth,0);assert.equal(w.health,1);assert.ok(w.effects.every(e=>e.ttl===198));});

test('all eight previously ignored treasure sprites use original high-value score entries',()=>{const expected=[10000,6000,2000,3000,1000,1000,2000,3000];for(let n=0;n<8;n++){const w=new World(a),i={sprite:110+n,x:100,y:600,active:true,authored:true};assert.equal(w.pickup(i),true);assert.equal(w.score,expected[n]);assert.equal(w.foodCounts[n],1);assert.equal(w.collectedFood,1);assert.equal(w.collectedAuthoredFood,1);assert.equal(w.health,3);assert.equal(w.weapon,0);}});
test('treasure bounces at native downward speed128 before it can be collected',()=>{const w=new World(a),i={sprite:111,x:100,y:600,active:true,vy:128,vx:0};assert.equal(w.pickup(i),false);assert.equal(i.active,true);assert.equal(i.vy,-128);assert.equal(Math.abs(i.vx),32);assert.equal(w.score,0);i.vy=127;assert.equal(w.pickup(i),true);assert.equal(w.score,6000);});
test('ordinary food scores every authored class through its original lookup and byte ledger',()=>{for(let c=75;c<=166;c++){const w=new World(a);w.pickup({sprite:c+53,x:100,y:600,active:true,authored:true});const index=c-57;assert.equal(w.score,[10,20,30,50,60,70,75,80,100,200,500,800,1000,2000,3000,6000,10000][w.byte(0xa371+index)],`class${c}`);assert.equal(w.foodCounts[index],1);assert.equal(w.health,3);}});
test('food ledger wraps bytes and dynamic food does not inflate authored completion',()=>{const w=new World(a);w.foodCounts[18]=255;w.collectedFood=65535;w.pickup({sprite:128,x:100,y:600,active:true});assert.equal(w.foodCounts[18],0);assert.equal(w.collectedFood,0);assert.equal(w.collectedAuthoredFood,0);w.pickup({sprite:128,x:100,y:600,active:true,authored:true});assert.equal(w.collectedAuthoredFood,1);assert.equal(w.totalFood,w.items.filter(i=>{const s=i.sprite&8191;return s>=110&&s<=117||s>=128&&s<=219;}).length);});
test('stage bonus repeats the food ledger values rather than a flat per-item amount',()=>{const w=new World(a);w.pickup({sprite:110,x:0,y:0,active:true});w.pickup({sprite:111,x:0,y:0,active:true});const score=w.score;w.transition={type:'complete',next:1};w.advance();assert.equal(w.score,score*2);assert.ok(w.foodCounts.every(n=>n===0));});
test('resuming modern and legacy browser saves does not award score lives twice',()=>{for(const saved of [{score:75000,lives:5},{score:75000,lives:5,extraLifeQuotient:3}]){const w=playerFixture();w.restoreScoreProgress(saved);w.step({});assert.equal(w.lives,5);assert.equal(w.extraLifeQuotient,3);w.score=100000;w.step({});assert.equal(w.lives,6);}});
test('all four weapon pickups match authored damage flags and do not alter health or score',()=>{for(const [c,weapon] of [[13,0],[182,1],[44,2],[224,3]]){const w=new World(a);w.health=1;w.score=777;const i={sprite:c+53,x:0,y:0,active:true};w.pickup(i);assert.equal(w.weapon,weapon);assert.equal(w.health,1);assert.equal(w.score,777);assert.equal(i.active,false);const table=0x7b00+weapon*5;assert.equal(w.byte(table+2),[2,6,6,12][weapon]);assert.equal(w.byte(table+3),[25,30,20,30][weapon]);assert.equal(w.byte(table+4),[0,0,1,3][weapon]);}});
test('health pickup remains available when full and life pickup caps at99 with original popup',()=>{const w=new World(a),i={sprite:226,x:0,y:0,active:true,authored:true};assert.equal(w.pickup(i),false);assert.equal(i.active,true);w.health=2;w.pickup(i);assert.equal(w.health,3);assert.equal(i.active,false);assert.ok(w.effects.some(e=>e.sprite===226));w.lives=99;w.pickup({sprite:227,x:0,y:0,active:true});assert.equal(w.lives,99);assert.ok(w.effects.some(e=>e.sprite===227&&e.x===w.player.x));});
test('harmful pickups eject all stored energy as recoverable bones and leave player alive',()=>{for(const sprite of [220,221]){const w=new World(a);w.health=2;w.foodHealth=3;w.pickup({sprite,x:100,y:600,active:true});assert.equal(w.health,0);assert.equal(w.foodHealth,0);assert.equal(w.deathTimer,0);assert.equal(w.player.invulnerable,44);const bones=w.effects.filter(e=>e.nativeObject);assert.equal(bones.length,15);assert.ok(bones.every(e=>e.collectible&&(e.sprite&8191)===70&&e.y===w.player.y-48));}});
test('five-item collection resets its mask and releases original treasure without weapon power',()=>{const w=new World(a);for(let c=39;c<=43;c++)w.pickup({sprite:c+53,x:0,y:0,active:true});assert.equal(w.inventory,0);assert.equal(w.collectionFlash,44);assert.equal(w.power,0);const reward=w.effects.find(e=>e.nativeObject);assert.equal(reward.sprite,110);assert.equal(reward.collectible,true);assert.equal(reward.y,w.player.y-112);});
test('repellent pickup affects point particles while retaining its food score',()=>{const w=new World(a);w.spawnFollowParticle();w.pickup({sprite:198,x:0,y:0,active:true,authored:true});assert.ok(w.particleRepel.every(n=>n===7));assert.equal(w.score,60);assert.equal(w.player.powerTimer,0);assert.equal(w.foodCounts[88],1);assert.equal(w.collectedAuthoredFood,1);w.frame=16;w.updateFollowParticles();assert.equal(w.particleRepel[0],6);});
test('enemy conversion pickup yields four foods without ordinary defeat score or bones',()=>{const {w,actor,d}=enemyFixture(9);d.flags=5;w.pickup({sprite:223,x:0,y:0,active:true});assert.equal(actor.active,false);assert.equal(w.score,0);const drops=w.effects.filter(e=>e.nativeObject);assert.equal(drops.length,4);assert.ok(drops.every(e=>(e.sprite&8191)>=128&&(e.sprite&8191)<=222&&e.collectible));assert.deepEqual(drops.map(e=>[e.vx,e.vy]),[[32,-160],[-32,-160],[16,-176],[-16,-176]]);});
test('palette switches interpolate to original dark colors and back instead of timed flashes',()=>{const w=new World(a);w.pickup({sprite:234,x:0,y:0,active:true});assert.equal(w.paletteMode,1);assert.equal(w.sceneFlash,0);for(let n=0;n<64;n++)w.updatePalette();const target=Array.from(w.assets.tables.subarray(0xacb3,0xace3),v=>Math.round(v*255/63));assert.deepEqual(w.paletteOverride.slice(0,48),target);w.pickup({sprite:233,x:0,y:0,active:true});for(let n=0;n<64;n++)w.updatePalette();assert.deepEqual(w.paletteOverride,w.assets.game.palettes[0].rgb8_scaled);});
test('decorative objects and an already active form remain in the level after contact',()=>{const w=new World(a),scenery={sprite:245,x:0,y:0,active:true,authored:true};assert.equal(w.pickup(scenery),false);assert.equal(scenery.active,true);w.alternate=true;const form={sprite:118,x:0,y:0,active:true,authored:true};assert.equal(w.pickup(form),false);assert.equal(form.active,true);});

function bossFixture(level=2){const w=new World(a);w.loadLevel(level);w.definitions=[];w.items=[];w.blocks=[];w.platforms=[];w.map.fill(0);w.level={...w.level,tilePropertiesY:Array(256).fill(0)};w.level.tilePropertiesY[1]=1;w.bossFloor=Math.min(50,w.level.height-2)*16;w.map.fill(1,(w.bossFloor>>4)*256);if(w.boss){w.boss.y=w.bossFloor;w.player.x=w.boss.x-150;w.player.y=w.bossFloor;w.camera={x:w.boss.x-160,y:w.bossFloor-160};}w.input={};return w;}
function bossShot(w,p,extra={}){return {x:p.x,y:p.y,sprite:67,ranged:true,ttl:1,damage:25,...extra};}
function specialTarget(w){const m=w.specialBoss,t=w.assets.rules.bosses.level6,row=m.stage===0?t.bodyFrames[m.bodyFrame]:m.stage===1?t.leftPartsFrames[m.leftFrame]:t.rightPartsFrames[m.rightFrame];return {x:row[0],y:row[1],sprite:row[2]};}
test('generic boss has distinct animation cursor, mirrors toward right and paints reverse pool order',()=>{for(const mirror of [false,true]){const w=bossFixture(),b=w.boss,data=w.assets.rules.bosses.generic;for(let pose=0;pose<data.poseTable.length;pose++){w.mem[0x7000]=pose;b.script=0x7000;b.mirror=mirror;w.bossParts=[];w.bossPose(b);assert.equal(b.parts.length,5);assert.deepEqual(w.bossParts,data.poseTable[pose].drawOrder.slice().reverse().map(i=>b.parts[i]));assert.equal(b.parts[0].sprite,data.poseTable[pose].sprites[0]^(mirror?32768:0));assert.ok(b.parts.every(p=>a.game.sprites[p.sprite&8191]));}}});
test('boss breathing offsets apply once to torso and independently to limbs',()=>{const w=bossFixture(),b=w.boss;w.mem[0x7000]=0;b.script=0x7000;w.bossPose(b);const parts=b.parts.map(p=>({...p}));w.mem[0x7000]=64;b.script=0x7000;w.bossPose(b);assert.equal(b.parts[0].y,parts[0].y);assert.equal(b.parts[1].y,parts[1].y+2);for(let i=2;i<5;i++)assert.equal(b.parts[i].y,parts[i].y+1);});
test('generic boss waits110 ticks and does not reset a repeatedly selected animation',()=>{const w=bossFixture(),b=w.boss;b.state=1;w.frame=1;w.updateBosses();assert.equal(b.stateAge,1);const cursor=b.script;w.frame++;w.updateBosses();assert.equal(b.script,cursor+1);for(let n=2;n<110;n++){w.frame++;w.updateBosses();}assert.equal(b.state,2);assert.equal(b.stateAge,0);assert.equal(b.anger,1);assert.equal(w.hazards.length,0);});
test('generic boss jump is tied to ticks44 and88 with native distance and speed formula',()=>{const w=bossFixture(8),b=w.boss;b.state=2;b.stateAge=43;w.updateBosses();assert.equal(b.vy,-224);b.vx=b.vy=0;b.y=w.bossFloor;b.stateAge=87;w.player.x=b.x-238;w.updateBosses();assert.equal(b.vy,-272);assert.equal(b.vx,-136);assert.equal(w.hazards.length,0);});
test('generic boss horizontal boundary rejects motion rather than clamping position',()=>{const w=bossFixture(),b=w.boss;b.x=b.maxX-2;b.vx=160;const x=b.x;w.player.x=x-200;w.updateBosses();assert.equal(b.x,x);});
test('generic boss weak point accepts head hits and preserves signed zero-HP boundary',()=>{const w=bossFixture(),b=w.boss;w.updateBosses();w.frame=23;b.hp=25;w.projectiles=[bossShot(w,b.parts[2])];assert.ok(w.overlap(w.projectiles[0],b.parts[2],true));w.updateBosses();assert.equal(b.hp,0);assert.equal(b.state,5);assert.equal(w.projectiles[0].ttl,0);w.frame=46;b.state=0;b.scriptStart=w.assets.rules.bosses.generic.scriptPointers.idle;b.script=b.scriptStart;b.vx=b.vy=0;b.y=w.bossFloor;w.bossPose(b);w.projectiles=[bossShot(w,b.parts[2])];w.updateBosses();assert.equal(b.hp,-25);assert.equal(b.state,6);assert.equal(b.vy,-128);});
test('generic boss hit interval is strictly greater than22 and axe does not force strong-hit state',()=>{const w=bossFixture(),b=w.boss;w.updateBosses();b.lastHit=0;w.frame=22;w.projectiles=[bossShot(w,b.parts[2],{damage:20})];w.updateBosses();assert.equal(b.hp,100);assert.equal(w.projectiles[0].ttl,1);w.frame=23;w.projectiles=[bossShot(w,b.parts[2],{damage:20})];w.updateBosses();assert.equal(b.hp,80);assert.notEqual(b.state,5);});
test('boss blocking arm absorbs weapon before the head can be hurt',()=>{const w=bossFixture(),b=w.boss,data=w.assets.rules.bosses.generic,pose=data.poseTable.findIndex(p=>[412,413].includes(p.sprites[3]));w.mem[0x7000]=pose;b.script=0x7000;w.bossPose(b);b.script=0x7000;b.state=0;w.frame=23;const shot=bossShot(w,b.parts[3]);w.projectiles=[shot];assert.ok(w.overlap(shot,b.parts[3],true));w.updateBosses();assert.equal(shot.ttl,0);assert.equal(b.hp,100);});
test('generic corpse emits sixteen native food rewards and a stationary key at last cluster',()=>{const w=bossFixture(),b=w.boss;b.state=6;b.vy=-16;b.drawn=[{x:1000,y:700}];w.updateBosses();assert.equal(b.active,false);const objects=w.effects.filter(e=>e.nativeObject);assert.equal(objects.length,17);const key=objects.find(e=>(e.sprite&8191)===99);assert.deepEqual([key.x,key.y,key.vx,key.vy],[936,668,0,0]);assert.equal(key.collectible,true);assert.equal(w.bossParts.length,0);});
test('generic contact injures in energy fragments and head landing bounces without hurting boss',()=>{const w=bossFixture(),b=w.boss;w.updateBosses();b.state=2;b.stateAge=0;const arm=b.parts[4];Object.assign(w.player,{x:arm.x,y:arm.y,vy:0});w.updateBosses();assert.ok(w.foodHealth>0);assert.ok(w.health>=2);assert.ok(w.effects.some(e=>e.nativeObject&&(e.sprite&8191)===70));assert.equal(w.player.invulnerable,44);});
test('multipart gate entry resets phases and timers on every entry',()=>{const w=bossFixture(5);w.activateSpecialBoss();w.specialBoss.stage=2;w.specialBoss.hp=1;w.specialBoss.attackDelay=0;w.activateSpecialBoss();const m=w.specialBoss;assert.deepEqual([m.hp,m.stage,m.hitTimer,m.bodyFrame,m.leftFrame,m.rightFrame,m.attackDelay,m.burst],[5,0,0,0,0,1,110,8]);assert.equal(w.bossLevelFlags&254,0);});
test('multipart phases use only staged weak point and all nineteen hits count during reaction animation',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:700,y:1900});for(let n=0;n<19;n++){w.frame++;const target=specialTarget(w);w.projectiles=[bossShot(w,target,{damage:1})];w.updateBosses();assert.equal(w.projectiles[0].ttl,0,`hit${n}`);if(n<4)assert.equal(w.specialBoss.stage,0);else if(n<11)assert.equal(w.specialBoss.stage,1);else if(n<18)assert.equal(w.specialBoss.stage,2);}assert.equal(w.specialBoss.stage,3);assert.equal(w.specialBoss.active,false);assert.equal(w.effects.filter(e=>e.nativeObject).length,17);const key=w.effects.find(e=>e.sprite===99);assert.ok([731,732].includes(key.x));assert.ok([1873,1875].includes(key.y));});
test('multipart wrong-part attack is neither consumed nor counted',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:700,y:1900});w.projectiles=[bossShot(w,{x:981,y:1985})];w.updateBosses();assert.equal(w.specialBoss.hp,5);assert.equal(w.projectiles[0].ttl,1);});
test('multipart rock spawns from attack delay then falls at constant speed without a lifetime timer',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:700,y:1900});for(let n=0;n<110;n++){w.frame++;w.updateBosses();}assert.equal(w.bossRocks.length,0);w.frame++;w.updateBosses();assert.equal(w.bossRocks.length,1);const r=w.bossRocks[0],vy=r.vy,y=r.y;w.specialBoss.attackDelay=200;for(let n=0;n<8;n++){w.frame++;w.updateBosses();}assert.equal(r.vy,vy);assert.equal(r.y,y+8*(vy>>4));assert.equal(r.ttl,undefined);assert.ok([435,436,437].includes(r.sprite));});
test('boss rocks bypass ordinary enemy immunity and remove one sixth of energy',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:700,y:1900,invulnerable:44});w.bossRocks=[{x:700,y:1900,sprite:435,vy:16,wobble:0,acceleration:4,active:true}];w.updateBosses();assert.equal(w.health,2);assert.equal(w.foodHealth,5);assert.equal(w.player.vx,-128);assert.equal(w.player.vy,-128);assert.equal(w.bossRocks.length,0);});
test('multipart boundary knocks player back without teleport clamp and costs one fragment',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:990,y:500,invulnerable:44});w.updateBosses();assert.equal(w.player.x,990);assert.equal(w.player.vx,-160);assert.equal(w.player.vy,-144);assert.equal(w.health,2);assert.equal(w.foodHealth,5);});
test('final boss bytecode preserves command-local cursor and native repeat trace',()=>{const w=bossFixture(9),expected=new Map([[1,[1,0xa518,5]],[24,[4,0xa52f,5]],[25,[1,0xa518,4]],[120,[4,0xa52f,1]],[121,[1,0xa518,0]],[122,[4,0xa557,1]],[139,[0,0xa568,1]],[143,[0,0xa56c,1]],[144,[4,0xa557,0]],[145,[1,0xa518,3]]]);for(let n=1;n<=145;n++){w.frame=n;w.updateBosses();if(expected.has(n))assert.deepEqual([w.finalBoss.pose,w.finalBoss.script,w.finalBoss.repeat],expected.get(n),`tick${n}`);}assert.ok(w.effects.some(e=>(e.sprite&8191)===458));});
test('final boss counts ranged rectangle hits without consuming projectiles but ignores melee',()=>{const w=bossFixture(9);const shot={x:185,y:30,sprite:274,ranged:true,ttl:1,damage:100};w.projectiles=[shot];w.updateBosses();assert.equal(w.finalBoss.hp,23);assert.equal(w.finalBoss.script,0xa53d);assert.equal(shot.ttl,1);w.updateBosses();assert.equal(w.finalBoss.hp,22);w.projectiles=[{...shot,ranged:false,contact:true}];w.updateBosses();assert.equal(w.finalBoss.hp,22);});
test('final boss attacks use native shared pool gravity and original spawn velocities and lifetimes',()=>{const w=bossFixture(9);w.finalBoss.repeat=1;w.finalBoss.script=0x7000;w.mem.set([255,254,0],0x7000);w.updateBosses();const h=w.effects.filter(e=>e.nativeObject);assert.equal(h.length,2);assert.deepEqual([h[0].sprite,h[0].x,h[0].y,h[0].vy,h[0].ttl],[458,200,88,0,132]);assert.equal(Math.abs(h[0].vx%8),0);assert.ok(h[0].vx<=0&&h[0].vx>=-120);assert.deepEqual([h[1].sprite,h[1].y,h[1].vx,h[1].vy,h[1].ttl],[459,0,0,0,66]);w.updateEffects();assert.equal(h[0].vy,9);assert.equal(h[1].vy,9);assert.equal(w.hazards.length,0);});
test('final boss defeat emits four moving exits once and draws defeated tile pose next tick',()=>{const w=bossFixture(9);w.finalBoss.hp=1;w.projectiles=[{x:200,y:50,sprite:274,ranged:true,ttl:1,damage:30}];w.updateBosses();assert.equal(w.finalBoss.hp,0);const exits=w.effects.filter(e=>e.sprite===0x2137);assert.equal(exits.length,4);assert.deepEqual(exits.map(e=>[e.vx,e.vy]),[[32,-160],[-32,-160],[16,-176],[-16,-176]]);w.updateBosses();assert.equal(w.finalBoss.pose,2);assert.equal(w.effects.filter(e=>e.sprite===0x2137).length,4);assert.equal(w.bossStatus.length,0);});
test('boss health icons follow native coarse divisions and screen coordinates',()=>{const w=bossFixture(9);w.updateBosses();assert.equal(w.bossStatus.length,6);assert.deepEqual(w.bossStatus.map(p=>[p.x,p.y,p.sprite]),Array.from({length:6},(_,i)=>[8+5*i,170,309]));w.finalBoss.hp=7;w.updateBosses();assert.equal(w.bossStatus.length,1);});
test('generic attack states use original duration branches and never invent projectiles',()=>{for(const [state,hp,timer,expected] of [[3,100,66,2],[3,50,154,2],[4,100,66,3],[5,100,19,1],[7,100,44,1]]){const w=bossFixture(),b=w.boss;Object.assign(b,{state,hp,stateAge:timer});w.updateBosses();assert.equal(b.state,expected,`state${state}`);assert.equal(w.hazards.length,0);assert.ok(!w.effects.some(e=>[458,459].includes(e.sprite&8191)));}});
test('multipart reaction byte underflow preserves native reads without crashing the renderer',()=>{const w=bossFixture(5);w.activateSpecialBoss();Object.assign(w.player,{x:700,y:1900});Object.assign(w.specialBoss,{stage:2,rightFrame:0,hitTimer:1,attackDelay:10});w.updateBosses();assert.equal(w.specialBoss.rightFrame,255);w.updateBosses();assert.ok(w.bossParts.every(p=>a.game.sprites[p.sprite&8191]));assert.deepEqual(w.specialBoss.unmappedPoseFrames,[255]);});
test('boss simulation state participates in replay checksums',()=>{const w=bossFixture(9),before=w.stateHash();w.finalBoss.hp--;assert.notEqual(w.stateHash(),before);});
test('landing solely on generic boss head bounces without reducing boss or player health',()=>{const w=bossFixture(),b=w.boss;w.updateBosses();b.state=2;const head=b.parts[2];w.player.y=head.y-a.game.sprites[head.sprite&8191].height+1;w.player.vy=32;let x;for(let d=-40;d<=40;d++){w.player.x=head.x+d;if(w.collisionDetails(w.player,head)?.topContact&&![3,4].some(i=>w.overlap(w.player,b.parts[i]))){x=w.player.x;break;}}assert.notEqual(x,undefined);w.input.up=true;w.updateBosses();assert.equal(w.player.vy,-128);assert.equal(w.health,3);assert.equal(b.hp,100);});

test('IDDQD prevents ordinary damage, form loss, energy spills and fatal terrain until toggled off',()=>{const {w,actor}=enemyFixture(9);w.input={};const original={health:w.health,food:w.foodHealth,lives:w.lives,flags:actor.def.flags};assert.equal(w.toggleGodMode(),true);w.alternate=true;Object.assign(w.player,{x:actor.x,y:actor.y,vy:0});w.checkActorDamage();w.damage();w.scatterHealth();for(const sprite of [220,221,458,459]){const i={sprite,x:0,y:0,active:true};w.pickup(i);assert.equal(i.active,false);}assert.equal(w.health,original.health);assert.equal(w.foodHealth,original.food);assert.equal(w.lives,original.lives);assert.equal(actor.def.flags,original.flags);assert.equal(w.alternate,true);assert.equal(w.player.invulnerable,0);assert.equal(w.effects.filter(e=>e.nativeObject).length,0);w.player.y=9999;w.loseLife();assert.equal(w.player.y,w.checkpoint.y);assert.equal(w.deathTimer,0);w.loadLevel(1);assert.equal(w.godMode,true);assert.equal(w.toggleGodMode(),false);w.damage();assert.equal(w.health,2);assert.equal(new World(a).godMode,false);});
test('IDDQD prevents generic and multipart boss contact damage and rock damage',()=>{const w=bossFixture(),b=w.boss;w.toggleGodMode();w.updateBosses();b.state=4;Object.assign(w.player,{x:b.parts[4].x,y:b.parts[4].y,vy:-1});w.updateBosses();assert.equal(w.health,3);assert.equal(w.foodHealth,0);assert.equal(w.player.invulnerable,0);const m=bossFixture(5);m.toggleGodMode();m.activateSpecialBoss();Object.assign(m.player,{x:1000,y:2000,vy:0});m.bossRocks=[{slot:0,x:1000,y:2000,sprite:435,vy:16,wobble:0,acceleration:4,active:true}];m.updateBosses();assert.equal(m.health,3);assert.equal(m.foodHealth,0);assert.equal(m.player.invulnerable,0);assert.equal(m.effects.filter(e=>e.nativeObject).length,0);assert.equal(m.bossRocks[0].active,true);});

test('IDDQD permits standing on spikes and crossing lethal side/ceiling tiles without checkpoint loops',()=>{const w=playerFixture();w.toggleGodMode();w.level.tilePropertiesY[1]=6;w.player.y=640;w.player.vy=32;w.collidePlayer(100,638);assert.equal(w.player.y,640);assert.equal(w.player.grounded,true);assert.equal(w.health,3);assert.equal(w.deathTimer,0);w.level.tilePropertiesX[2]=2;w.level.tilePropertiesMisc[2]=2;w.map[(39<<8)|6]=2;w.map[(38<<8)|6]=2;Object.assign(w.player,{x:104,y:640,vy:-16});w.collidePlayer(100,640);assert.equal(w.player.x,104);assert.equal(w.deathTimer,0);const normal=playerFixture();normal.level.tilePropertiesY[1]=6;normal.player.vy=32;normal.collidePlayer(100,638);assert.ok(normal.deathTimer>0);});
test('final boss reward leads to F before the ending and keeps cheats across transition',()=>{const w=new World(a);w.loadLevel(9);w.toggleGodMode();w.toggleSecretHints();w.finalBoss.hp=0;w.pickup({sprite:0x2137,x:185,y:30,active:true});assert.equal(w.transition.type,'complete');assert.equal(w.transition.next,14);for(let n=0;n<58;n++)w.step({});w.advance();assert.equal(w.level.id,'F');assert.equal(w.godMode,true);assert.equal(w.secretHints,true);w.player.y=(w.level.height+1)*16+1;w.step({});assert.equal(w.transition.type,'ending');});

test('authored platform shuttle decodes direction/speed/duration instead of invented coordinate bounds',()=>{const w=playerFixture(),raw=[100,0,244,1,43,1,130,3,255,255,2,0,0,0,0],copy=raw.slice();const p=w.makePlatform({index:0,x:100,y:500,sprite:299,raw});w.platforms=[p];const xs=[];for(let n=0;n<11;n++){w.updatePlatforms();xs.push(p.x);}assert.deepEqual(xs,[101,103,106,109,111,112,112,111,109,106,103]);assert.equal(p.raw[7],3);assert.deepEqual(raw,copy);});
test('rider-triggered platforms wait, carry both axes, then continue through their return motion',()=>{const w=playerFixture(),p=w.makePlatform({index:7,x:100,y:600,sprite:299,raw:[100,0,88,2,43,1,1,2,255,255,3,0,0,0,0]});w.platforms=[p];for(let n=0;n<20;n++)w.updatePlatforms();assert.equal(p.x,100);p.raw[6]|=64;Object.assign(w.player,{x:100,y:w.spriteBounds(p).top,platformGrip:true,platformId:7,vy:0});const y=w.player.y;w.updatePlatforms();assert.equal(p.x,101);assert.equal(p.y,599);assert.equal(w.player.x,101);assert.equal(w.player.y,y);assert.equal(w.player.vy,1);assert.equal(w.carriedPlatform,7);w.player.platformGrip=false;for(let n=0;n<30;n++)w.updatePlatforms();assert.ok(p.x!==101);});
test('falling platforms wait their authored rider delay and recover to the original height after leaving',()=>{const w=playerFixture(),p=w.makePlatform({index:0,x:100,y:500,sprite:304,raw:[100,0,244,1,48,1,8,0,255,2,0,0,0,2,255]});w.platforms=[p];for(let n=0;n<5;n++)w.updatePlatforms();assert.equal(p.y,500);p.raw[6]|=64;w.updatePlatforms();assert.equal(p.raw[13],1);p.raw[6]|=64;w.updatePlatforms();assert.equal(p.raw[10],1);for(let n=0;n<40;n++)w.updatePlatforms();assert.ok(p.y>500);for(let n=0;n<100;n++)w.updatePlatforms();assert.equal(p.y,500);assert.equal(p.raw[10],0);});

test('all 44 authored gate records teleport and select their authored camera on an ordinary Down tick',()=>{let count=0;for(let index=0;index<16;index++)for(const g of a.game.levels[index].gates.filter(g=>g.active)){const w=new World(a);w.loadLevel(index);w.toggleGodMode();Object.assign(w.player,{x:(g.triggerTile&255)*16,y:(g.triggerTile>>8)*16,vx:0,vy:0});let seen=false;w.onEvent=e=>{if(e.type==='sfx'&&e.index===3){seen=true;assert.equal(w.player.x,(g.destinationTile&255)*16);assert.equal(w.player.y,(g.destinationTile>>8)*16);assert.equal(w.camera.x,(g.cameraTile&255)*16);assert.equal(w.camera.y,(g.cameraTile>>8)*16);assert.equal(w.gateCameraFlag,g.cameraFlag);}};w.step({down:true});assert.ok(seen,`stage${index} gate${g.index}`);count++;}assert.equal(count,44);});
test('all authored secret blocks have bounded hit resolution, valid replacement tiles and valid reward art',()=>{let count=0;for(let index=0;index<16;index++){const base=new World(a);base.loadLevel(index);for(const seed of base.blocks){const w=new World(a);w.loadLevel(index);const b=w.blocks.find(b=>b.index===seed.index);for(let n=0;n<257&&b.active;n++){w.blockCooldown=0;w.hitBlock(b);}assert.equal(b.active,false,`stage${index} block${seed.index}`);assert.equal(w.map[b.pos],b.replacement);for(const e of w.effects)assert.ok(e.sprite===undefined||e.sprite===65535||a.game.sprites[e.sprite&8191]);count++;}}assert.ok(count>300);});

test('rising elevators retain riders through acceleration using native top-plus-one contact branch',()=>{const w=playerFixture(),p=w.makePlatform({index:0,x:100,y:500,sprite:299,raw:[100,0,244,1,43,1,128,6,255,255,50,0,0,0,0]});w.platforms=[p];Object.assign(w.player,{x:100,y:w.spriteBounds(p).top,platformGrip:true,platformId:0,grounded:true,vy:0});for(let n=0;n<30;n++){w.step({});assert.equal(w.player.y,w.spriteBounds(p).top+1);assert.equal(w.player.vy,1);assert.equal(w.player.platformGrip,true);}assert.ok(p.y<350);});
test('descending elevators pass their vertical velocity into supported player movement',()=>{const w=playerFixture(),p=w.makePlatform({index:0,x:100,y:500,sprite:299,raw:[100,0,244,1,43,1,132,2,255,255,50,0,0,0,0]});w.platforms=[p];Object.assign(w.player,{x:100,y:w.spriteBounds(p).top,platformGrip:true,platformId:0,grounded:true,vy:0});for(let n=0;n<10;n++){w.step({});assert.equal(w.player.y,w.spriteBounds(p).top);assert.equal(w.player.vy,p.dy*16);assert.equal(w.player.platformGrip,true);}});

test('bear rebound retains the descending jump lock and follows one gravity update, not a new jump',()=>{
 for(const [held,impulse,height]of [[false,-64,10],[true,-224,105]]){const {w,actor}=enemyFixture(9),top=actor.y-a.game.sprites[actor.sprite&8191].height;Object.assign(w.player,{x:actor.x,y:top+2,vy:128,jumpLock:6,jumpFrame:9,fallFrames:20});w.input={up:held};w.checkActorDamage();assert.equal(w.player.vy,impulse);assert.equal(w.player.fallFrames,0);assert.equal(w.player.jumpLock,6);w.actors=[];w.definitions=[];w.map.fill(0);let apex=w.player.y;const trace=[];for(let i=0;i<18;i++){w.step({up:held});apex=Math.min(apex,w.player.y);trace.push([w.player.y,w.player.vy]);}assert.equal(top-apex,height);assert.deepEqual(trace[0],[top+(impulse>>4),impulse+16]);assert.equal(w.health,3);}
});
